/**
 * vite-plugin-patch-vendor — Vite plugin
 * In watch mode (dev), fires on each rebuild via closeBundle hook.
 * Patches vendor.js to:
 *   1. Export `reactive` alongside `ref`
 *   2. Remove broken `nref;` statements generated by compiler bug with @dcloudio/uni-app imports
 * Guarded to be idempotent: skips if already patched.
 */
import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

export default function patchVendorPlugin() {
  return {
    name: 'patch-vendor',
    closeBundle() {
      const vendorPath = path.resolve(
        __dirname, '..', 'dist', 'dev', 'mp-weixin', 'common', 'vendor.js'
      )
      if (!fs.existsSync(vendorPath)) return

      let content = fs.readFileSync(vendorPath, 'utf8')
      let modified = false

      // ── Patch 1: Add missing reactive export ──
      if (!content.includes('exports.reactive = reactive;')) {
        if (content.includes('exports.ref = ref;')) {
          content = content.replace(
            'exports.ref = ref;',
            'exports.ref = ref;\nexports.reactive = reactive;'
          )
          console.log('[patch-vendor] ✅ reactive patch applied')
          modified = true
        } else {
          console.warn('[patch-vendor] ⚠️  anchor "exports.ref = ref;" not found, skipping reactive patch')
        }
      }

      // ── Patch 2: Remove broken nref; or bare assignment statements ──
      if (/^nref;$/m.test(content) || /^\s*=\s*\w+;$/m.test(content)) {
        content = content.replace(/^(?:nref|=\s*\w+);\n?/gm, '')
        console.log('[patch-vendor] ✅ nref/bare-assignment cleanup applied')
        modified = true
      }

      if (modified) {
        fs.writeFileSync(vendorPath, content, 'utf8')
      }
    }
  }
}
